  public function executeUpdateRadicar()
  {
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$reg = $this->getRegionalFirma($usuariologuiado);  	
  	/*************************************Radicar el prestamo en la base de datos**********************************/
  	$radicar_prestamo = new ClPrestamo();
  	$radicar_prestamo->setClEstadoprestamoId(1);
  	$radicar_prestamo->setUsuarioId($usuariologuiado);
  	$radicar_prestamo->setRegionalId($reg);
  	$radicar_prestamo->setPeriodoId(date("Y"));
  	$radicar_prestamo->setFechaPrestamo(date("Y-m-d"));
  	$radicar_prestamo->setFechaVencimiento($this->getFechaVence());
  	//$radicar_prestamo->setFechaDevolucion();
  	$radicar_prestamo->setObservaciones($this->getRequestParameter('observaciones'));
  	$radicar_prestamo->setConsecutivoRegional($this->formatoRadicar());  	  	
  	$radicar_prestamo->setNumeroRadicacion($this->getNumRadicacion($reg));
  	$radicar_prestamo->save();
  	//$this->setFechaVence($radicar_prestamo->getPrestamoId(),$radicar_prestamo->getFechaPrestamo());
  	/**************************************************************************************************************/
  	
  	/*****************************Radicar los Detalles Del prestamo en la base de datos****************************/
  	$cadSolicitud   = $this->getUser()->getAttribute('solicitud_cliente','','prestamo_cliente');
  	$solicitudes_id = split(",",$cadSolicitud);
  	for($i = 0; $i < count($solicitudes_id); $i++){
	  	//Creas los detalles del prestamo con los ids de las solicitudes.	  				
	  	$detalles_prestamo = new ClDetallePrestamo();
	  	$detalles_prestamo->setClPrestamoId($radicar_prestamo->getClPrestamoId());
	  	$detalles_prestamo->setClEstadoprestamoId(1);
	  	$detalles_prestamo->setClSolicitudprestamoId($solicitudes_id[$i]);
	  	$detalles_prestamo->save();
	  	//Actualiza los estados de la solicitud y la fecha de atencion 
	  	$solicitudes  = ClSolicitudPrestamoPeer::retrieveByPK($solicitudes_id[$i]);
	  	$solicitudes->setClSolicitudprestamoestadoId(2);
	  	$solicitudes->setFechaAtencion(date("y-m-d G:i:s"));
	  	$solicitudes->save();
	}
	
  	/**************************************************************************************************************/  	
  	
  	/***********************Borrar Los IDs De solicitudes en la Variable de sesion*********************************/
  	$this->getUser()->setAttribute('solicitud_cliente', "", 'prestamo_cliente');
  	$this->redirect('solicitud_prestamo_cliente/imprimir?opcion=0&clprestamo_id='.$radicar_prestamo->getClPrestamoId());
  	/**************************************************************************************************************/
  }
  
  public function executeImprimir()
  {
