  public function executeUpdate()
  {
    if (!$this->getRequestParameter('clsolicitudprestamo_id'))
    {
      $cl_solicitud_prestamo = new ClSolicitudPrestamo();
    }
    else
    {
      $cl_solicitud_prestamo = ClSolicitudPrestamoPeer::retrieveByPk($this->getRequestParameter('clsolicitudprestamo_id'));
      $this->forward404Unless($cl_solicitud_prestamo);
    }
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $cl_solicitud_prestamo->setClsolicitudprestamoId($this->getRequestParameter('clsolicitudprestamo_id'));
    $cl_solicitud_prestamo->setClienteId($this->getRequestParameter('cliente_id'));
    $cl_solicitud_prestamo->setUsuarioId($usuariologuiado);
    $cl_solicitud_prestamo->setClsolicitudprestamoestadoId(1);    
    $cl_solicitud_prestamo->setFechaCreacion(date("Y-m-d G:i:s"));    
    if ($this->getRequestParameter('fecha_atencion'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_atencion'), $this->getUser()->getCulture());
      $cl_solicitud_prestamo->setFechaAtencion("$y-$m-$d");
    }

    $cl_solicitud_prestamo->save();

    return $this->redirect($this->getRequest()->getScriptName().'/cliente/show?cliente_id='.$cl_solicitud_prestamo->getClienteId());
  }
  
