  public function getNumRadicacion($regional)
  {
    $periodoActual = date("Y");
    $parametro = ParametroPeer::retrieveByPk(39);
    $formaRad = $parametro->getCodigo();
    $conexion = Propel::getConnection();
    //************************************************************************************
    if ($formaRad == "REG") {
        $consulta = "SELECT MAX(%s) AS max FROM %s where %s=" . $regional . "  and %s=" .$periodoActual . " ";
        $consulta = sprintf($consulta, ClPrestamoPeer::NUMERO_RADICACION, ClPrestamoPeer::TABLE_NAME, ClPrestamoPeer::REGIONAL_ID, ClPrestamoPeer::PERIODO_ID);
    } elseif ($formaRad == "GEN") {
        $consulta = "SELECT MAX(%s) AS max FROM %s where  %s=" . $periodoActual . " ";
        $consulta = sprintf($consulta, ClPrestamoPeer::NUMERO_RADICACION, ClPrestamoPeer::TABLE_NAME, ClPrestamoPeer::PERIODO_ID);
    }
    //************************************************************************************
    $sentencia = $conexion->prepare($consulta);
    $sentencia->execute();
    $resultset = $sentencia->fetch(PDO::FETCH_OBJ);
    return ($resultset->max + 1);
    //************************************************************************************        
  }
  
  public function formatoRadicar()
  {
    $periodoActual = date("Y");
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$reg = $this->getRegionalFirma($usuariologuiado);    	
    $max = $this->getNumRadicacion($reg);        
    $cad = sprintf("%02d-%05d",$reg, $max);        
    return $cad;
  }
    
  public function getRegionalFirma($userId)
  {
    // consultar regional firmante inicial.
    $firmante = '';
    $c = new Criteria();        
    $c->add(UsuarioPeer::USUARIO_ID, $userId);
    $result = UsuarioPeer::doSelectOne($c);        
    $firmante = $result->getRegionalId();                
    return $firmante;
  }
  
  public function getFechaVence()
  {
  	//calcula la fecha de vencimiento del prestamo segun la dependencia del usuario logueado
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$usuario  = UsuarioPeer::retrieveByPK($usuariologuiado);
	$dias_prestamo  = $usuario->getDependencia()->getTiempoPrestamo();
	$vence   = AddDays(date("Y-m-d"),$dias_prestamo);
	return $vence;	
  }
